/* 자동 생성 파일: 직접 수정하지 말고 tools/build_popup_bundle.py를 다시 실행하세요. */
window.KEPCO_POPUP_BUNDLE = Object.assign(window.KEPCO_POPUP_BUNDLE || {}, {
"popups/PartnerRegister/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionStep1Title\">\n          <h3 id=\"descriptionStep1Title\">STEP 01 · 약관 및 개인정보 수집 동의</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">기존의 이용약관, 개인정보 수집·이용 동의 내용 확인 후 현행화 필요  </pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionStep2aTitle\">\n          <h3 id=\"descriptionStep2aTitle\">STEP 02 · 기본 정보 입력</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">사업자등록번호 중복 시 협력업체 신청 불가\n\n“이미 협력업체로 등록되어 있습니다.”</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">비밀번호 생성 규칙(공공기관 기준) : 영문/숫자/특수기호 조합 8~20자 </pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">전화번호/핸드폰 앞자리 : 02, 031, 032, 033, 041, 042, 043, 044, 051, 052, 053, 054, 055, 061, 062, 063, 064, 010, 070</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">주소 검색 API를 활용하여 개발</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionStep2bTitle\">\n          <h3 id=\"descriptionStep2bTitle\">STEP 02 · 관련 증빙서류 제출</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">5</span>\n              <pre class=\"description-source-text\">첨부 파일 확장자 : (공통 적용),\n\nhwp, hwpx\ndoc, docx\nxls, xlsx\nppt, pptx\npdf\nzip\n\n이 영역에서는 PDF만 입력되도록 할 것인지 확인 필요</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">6</span>\n              <pre class=\"description-source-text\">AAA, AA+, AA, AA-, A+, A, A-, BBB+, BBB, BBB-, BB+, BB, BB-, B+, B, B-, CCC, CC, C, D</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionStep3Title\">\n          <h3 id=\"descriptionStep3Title\">STEP 03 · 담당자 정보 입력</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">이메일 입력 서식에 공통 적용\n\n직접 입력\nnaver.com\ngoogle.com\nhanmail.net\ndaum.net\nnate.com</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionStep5Title\">\n          <h3 id=\"descriptionStep5Title\">STEP 05 · 협력업체 신청 완료</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">고객 통보 : MSG-001</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>",
"popups/SRMLogin/modalBiddingDetail.html": "<div class=\"modal-backdrop\" id=\"modalBiddingDetail\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"biddingModalTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog modal-lg\">\n    <div class=\"modal-header\">\n      <h2 class=\"modal-title\" id=\"biddingModalTitle\">입찰공고 내역서 상세</h2>\n      <button type=\"button\" class=\"modal-close\" id=\"btnCloseBiddingModal\" aria-label=\"닫기\">&times;</button>\n    </div>\n      <div class=\"modal-body\">\n        <p class=\"modal-desc\">입찰 진행사: 켑코이에스(주)</p>\n        <table class=\"data-table\" aria-label=\"입찰공고 기본정보\">\n          <tbody>\n            <tr>\n              <th>공고번호</th>\n              <td>BD2026-0025</td>\n              <th>상태</th>\n              <td>입찰공고</td>\n            </tr>\n            <tr>\n              <th>입찰담당자</th>\n              <td>이길수</td>\n              <th>개찰담당자</th>\n              <td>박승길</td>\n            </tr>\n            <tr>\n              <th>입찰건명</th>\n              <td colspan=\"3\">서초동 1601-9 오피스텔 신축공사 중 기계식주차설비공사</td>\n            </tr>\n          </tbody>\n        </table>\n\n        <p class=\"modal-desc content-object-gap-top\">입찰 진행 방법</p>\n        <table class=\"data-table\" aria-label=\"입찰 진행 방법\">\n          <tbody>\n            <tr><th>구분</th><td colspan=\"3\">공사</td></tr>\n            <tr><th>계약방법</th><td>경쟁입찰(일반)</td><th>낙찰자 선정방법</th><td>제한적 최저가 입찰</td></tr>\n            <tr><th>수행기간</th><td>2026-08-20 ~ 2027-06-30</td><th>수행기간(일수)</th><td>314일</td></tr>\n            <tr><th>납품장소(현장)</th><td colspan=\"3\">현장 내</td></tr>\n          </tbody>\n        </table>\n\n        <p class=\"modal-desc content-object-gap-top\">보증금률</p>\n        <table class=\"data-table\" aria-label=\"보증금률\">\n          <tbody>\n            <tr><th>입찰 보증금률</th><td>5%</td><th>계약이행 보증금률</th><td>10%</td></tr>\n            <tr><th>하자이행 보증금률</th><td>3%</td><th>하자이행 기간</th><td>3년</td></tr>\n          </tbody>\n        </table>\n\n        <p class=\"modal-desc content-object-gap-top\">입찰 일정 계획</p>\n        <table class=\"data-table\" aria-label=\"입찰 일정 계획\">\n          <tbody>\n            <tr><th>입찰 시작일시</th><td>2026-08-04 16:00</td><th>공급업체 등록마감일</th><td>2026-08-10</td></tr>\n            <tr><th>현장설명회(일시/장소)</th><td colspan=\"3\">-</td></tr>\n            <tr><th>입찰참가 신청마감일시</th><td>2026-08-11 16:00</td><th>입찰 마감일시</th><td class=\"text-danger\">2026-08-18 16:00</td></tr>\n            <tr><th>제안발표(일시/장소)</th><td colspan=\"3\">-</td></tr>\n          </tbody>\n        </table>\n\n        <p class=\"modal-desc content-object-gap-top\">입찰업체 전달내역</p>\n        <table class=\"data-table\" aria-label=\"입찰업체 전달내역\">\n          <tbody>\n            <tr><th>업체 자격요건</th><td colspan=\"3\">승강기·삭도공사업 면허 보유업체</td></tr>\n            <tr><th>참여신청 제출서류</th><td colspan=\"3\">1. 입찰참가신청서.hwp</td></tr>\n            <tr><th>입찰 제출서류</th><td colspan=\"3\">2. 입찰보증금지급각서.hwp</td></tr>\n            <tr><th>전달사항(비고)</th><td colspan=\"3\">입찰공고문의 입찰 참가자격, 참가신청 및 낙찰자 결정방법을 숙지하여 주시기 바랍니다.</td></tr>\n            <tr><th>입찰업체 배포서류</th><td colspan=\"3\">00. 입찰공고문_재공고(서초동 1601-9 오피스텔 신축공사 중 기계식주차설비공사).pdf</td></tr>\n          </tbody>\n        </table>\n\n        <p class=\"modal-desc content-object-gap-top\">입찰 품목</p>\n        <table class=\"data-table\" aria-label=\"입찰 품목\">\n          <thead><tr><th>품목명</th><th>규격</th><th>단위</th><th>수량</th><th>비고</th></tr></thead>\n          <tbody>\n            <tr><td colspan=\"1\">서초동 1601-9 오피스텔 신축공사 중 기계식주차 설비공사</td><td>-</td><td>식</td><td>1</td><td>-</td></tr>\n          </tbody>\n        </table>\n      </div>\n      <div class=\"modal-footer\">\n                  <button type=\"button\" class=\"btn-form-submit\" id=\"btnJoinBidding\">입찰 참가신청 (로그인 필요)</button>\n        <button type=\"button\" class=\"btn-form-prev\" id=\"btnCloseBiddingAction\">닫기</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMLogin/modalIdFind.html": "<div class=\"modal-backdrop\" id=\"modalIdFind\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"idFindModalTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"idFindModalTitle\">아이디 찾기</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box\" role=\"note\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4\"/><path d=\"M12 8h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">본 입찰시스템의 아이디는 협력업체의 '사업자등록번호'입니다.</p>\n            <p>사업자등록번호의 숫자만 입력해 주세요. 문의사항은 02-6959-4561로 연락 부탁드립니다.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMLogin/modalPwFind.html": "<div class=\"modal-backdrop\" id=\"modalPwFind\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pwFindModalTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog modal-lg\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pwFindModalTitle\">비밀번호 찾기</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box\" role=\"note\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><circle cx=\"12\" cy=\"12\" r=\"10\"/><path d=\"M12 16v-4\"/><path d=\"M12 8h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">비밀번호를 찾기 위해서는 협력업체 신청 시 등록한 담당자의 정보 확인이 필요합니다.</p>\n            <p>정보가 확인되면 담당자의 이메일로 '임시 비밀번호'가 발송됩니다. 문의사항은 02-6959-4561로 연락 부탁드립니다.</p>\n          </div>\n        </div>\n        <div class=\"srm-kv-grid content-inner-gap-top description-marker-container\">\n          <span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">1</span>\n          <div class=\"srm-kv-row\"><dt>사업자등록번호(아이디) <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control w-160\" placeholder=\"숫자로만 입력해 주세요.\"></dd></div>\n          <div class=\"srm-kv-row\"><dt>담당자 이메일 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control w-140 inline-control\"> @ <select class=\"filter-select w-150 inline-control\"><option>이메일 선택</option><option>직접 입력</option></select></dd></div>\n          <div class=\"srm-kv-row\"><dt>담당자 핸드폰 번호 <span class=\"required\" aria-hidden=\"true\">*</span></dt><dd><input type=\"text\" class=\"form-control w-60 inline-control\" value=\"010\"> - <input type=\"text\" class=\"form-control w-60 inline-control\"> - <input type=\"text\" class=\"form-control w-60 inline-control\"></dd></div>\n        </div>\n      </div>\n      <div class=\"modal-footer\">\n        <span class=\"description-marker-anchor\">\n          <span class=\"description-target-marker\" aria-hidden=\"true\">3</span>\n          <button type=\"button\" class=\"btn-primary\" id=\"btnPwFindSubmit\" data-close-modal data-open-modal=\"modalPwFindSent\">비밀번호 찾기</button>\n        </span>\n        <button type=\"button\" class=\"btn-secondary modal-close\">닫기</button>\n      </div>\n    </div>\n  </div>",
"popups/SRMLogin/modalPwFindMismatch.html": "<div class=\"modal-backdrop\" id=\"modalPwFindMismatch\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pwFindMismatchTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pwFindMismatchTitle\">정보 불일치 안내</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box warning\" role=\"alert\">\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M12 3 2.5 20h19L12 3Z\"/><path d=\"M12 10v4\"/><path d=\"M12 17h.01\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">입력하신 정보가 일치하지 않습니다.</p>\n            <p>정보가 확인되지 않은 경우 '임시 비밀번호'를 발송할 수 없습니다. 문의사항은 02-6959-4561로 연락 부탁드립니다.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMLogin/modalPwFindSent.html": "<div class=\"modal-backdrop\" id=\"modalPwFindSent\" role=\"dialog\" aria-modal=\"true\" aria-labelledby=\"pwFindSentTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"pwFindSentTitle\">비밀번호 찾기</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body\">\n        <div class=\"notice-box success description-marker-container\" role=\"note\">\n          <span class=\"description-target-marker marker-top-left\" aria-hidden=\"true\">2</span>\n          <span class=\"notice-icon\" aria-hidden=\"true\"><svg aria-hidden=\"true\" viewBox=\"0 0 24 24\"><path d=\"M20 6 9 17l-5-5\"/></svg></span>\n          <div class=\"notice-body\">\n            <p class=\"notice-lead\">담당자의 이메일(leeh**43@n*ver.com)로 '임시 비밀번호'가 전송되었습니다.</p>\n            <p>임시 비밀번호로 로그인 후 반드시 '비밀번호'를 변경해 주세요.</p>\n          </div>\n        </div>\n      </div>\n      <div class=\"modal-footer\"><button type=\"button\" class=\"btn-secondary modal-close\">닫기</button></div>\n    </div>\n  </div>",
"popups/SRMLogin/screenDescriptionGuide.html": "<div class=\"modal-backdrop description-guide-backdrop\" id=\"screenDescriptionGuide\" role=\"dialog\" aria-modal=\"false\" aria-labelledby=\"screenDescriptionGuideTitle\" aria-hidden=\"false\">\n    <div class=\"modal-dialog modal-lg description-modal-dialog\">\n      <div class=\"modal-header\">\n        <h2 class=\"modal-title\" id=\"screenDescriptionGuideTitle\">화면설계 Description</h2>\n        <button type=\"button\" class=\"modal-close\" aria-label=\"닫기\">&times;</button>\n      </div>\n      <div class=\"modal-body description-modal-body\">\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionLoginTitle\">\n          <h3 id=\"descriptionLoginTitle\">로그인</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">켑코이에스 또는 전자입찰시스템(SRM)을 홍보/표현해 줄 수 있는 핵심 메시지 제공 필요</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">로그인 문의를 담당해 줄 직원과 연락처 제공 필요 </pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">협력업체(관리자에 의해 승인된)만 로그인 가능\n\n승인된 협력업체일지라도 관리자에 의해 사용 여부가 N(사용 안 함)인 경우 로그인 불가</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">4</span>\n              <pre class=\"description-source-text\">입찰공고 내역서: 뒤 페이지 팝업 호출</pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionIdFindTitle\">\n          <h3 id=\"descriptionIdFindTitle\">아이디 찾기(팝업)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <pre class=\"description-source-text\">팝업으로 사업자등록번호(숫자)가 아이디임을 안내함 </pre>\n            </div>\n          </div>\n        </section>\n        <section class=\"description-source-section\" aria-labelledby=\"descriptionPwFindTitle\">\n          <h3 id=\"descriptionPwFindTitle\">비밀번호 찾기(팝업)</h3>\n          <div class=\"description-mapping-list\">\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">1</span>\n              <pre class=\"description-source-text\">협력업체는 다수(N)의 담당자가 등록될 수 있으며, 등록된 담당자의 정보와 일치하면 비밀번호 찾기 제공(매칭된 담당자의 이메일)\n</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">2</span>\n              <pre class=\"description-source-text\">이메일 주소는 일부를 마스킹 처리할 것\n\n마스킹 규칙 : 개발자 자유\n임시 비밀번호 발송 : 비밀번호 생성 규칙(영문/숫자/특수기호 조합 8~20자) 기준을 준수하는 범위에서 개발자 자유</pre>\n            </div>\n            <div class=\"description-mapping-item\">\n              <span class=\"description-mapping-number\" aria-hidden=\"true\">3</span>\n              <pre class=\"description-source-text\">고객 통보 : MSG-002</pre>\n            </div>\n          </div>\n        </section>\n      </div>\n    </div>\n  </div>"
});
